def parse_duration(s: str) -> int:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")
    tokens = s.split()
    units = []
    total_seconds = 0

    for token in tokens:
        if len(token) < 2:
            raise ValueError("Invalid token")
        unit_char = token[-1].lower()
        if unit_char not in {'h', 'm', 's'}:
            raise ValueError("Unknown unit")
        number_part = token[:-1]
        try:
            num = int(number_part)
        except ValueError:
            raise ValueError("Invalid number part")
        if num < 0:
            raise ValueError("Negative number")
        units.append(unit_char)
        if unit_char == 'h':
            total_seconds += num * 3600
        elif unit_char == 'm':
            total_seconds += num * 60
        elif unit_char == 's':
            total_seconds += num

    ordered_units = ['h', 'm', 's']
    for i in range(len(units)):
        if i >= len(ordered_units):
            raise ValueError("Units out of order")
        if units[i] != ordered_units[i]:
            raise ValueError("Units out of order")

    return total_seconds
