def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    first_valid_name = {}
    customer_totals = {}
    for row in rows:
        customer = row.get('customer', '').strip()
        if not customer:
            continue
        amount_str = row.get('amount', '').replace('$', '').replace(',', '')
        try:
            amount = float(amount_str)
        except ValueError:
            continue
        lower_name = customer.lower()
        if lower_name not in first_valid_name:
            first_valid_name[lower_name] = customer
        if lower_name not in customer_totals:
            customer_totals[lower_name] = 0.0
        customer_totals[lower_name] += amount
    result = []
    for lower_name in customer_totals:
        name = first_valid_name[lower_name]
        total = round(customer_totals[lower_name], 2)
        result.append((name, total))
    result.sort(key=lambda x: (-x[1], x[0]))
    return result[:n]
